{"passages":[
    {
      "id": "m20",
      "about_topic": true,
      "says": "fact: pavement markings tell a driver when it is not safe to pass (other purposes listed are not about the topic)"
    },
    {
      "id": "m21",
      "about_topic": true,
      "says": "rule: a solid line at the left of the lane means it is unsafe to pass; should not pass"
    },
    {
      "id": "m22",
      "about_topic": true,
      "says": "figure: vehicles travelling beside a solid yellow line (illustrates the solid line rule)"
    },
    {
      "id": "m23",
      "about_topic": true,
      "says": "rule: a broken line at the left of the lane means you may pass if the way is clear; enough broken lines ahead to complete the pass safely"
    },
    {
      "id": "m24",
      "about_topic": true,
      "says": "figure: vehicles travelling beside broken yellow lines (illustrates the broken line rule)"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT pavement markings tell a driver when it is not [?safe] to pass",
      "sources": [
        {
          "id": "m20",
          "quote": "Pavement markings divide traffic lanes, show turning lanes, mark pedestrian crossings, indicate obstacles and tell you when it is not safe to pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safe",
          "note": "No measure of safety is given; the driver must judge whether passing is safe."
        }
      ],
      "links": [],
      "note": "Only the passing-related purpose is extracted; the other purposes (dividing lanes, showing turning lanes, marking crossings, indicating obstacles) are not about the topic."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "text (\"should not\")",
      "text": "a driver SHOULD NOT pass WHEN there is a solid line at the left of the driver's lane BECAUSE it is [?unsafe] to pass",
      "sources": [
        {
          "id": "m21",
          "quote": "A solid line at the left of your lane means it is unsafe to pass. ('A' should not pass.)"
        },
        {
          "id": "m22",
          "quote": "vehicles travelling beside a solid yellow line"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "unsafe",
          "note": "No measure of safety is given; the driver must judge whether passing is unsafe."
        }
      ],
      "links": [],
      "note": "The main sentence describes the line's meaning ('it is unsafe to pass'); the parenthetical gives the advisory instruction ('should not pass'). The force is advisory from 'should not', not legal, because the handbook does not use legal wording for this marking."
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may pass\")",
      "text": "a driver MAY pass WHEN there is a broken line at the left of the driver's lane AND the way is [?clear] AND there are [?enough] broken lines ahead to complete the pass [?safely]",
      "sources": [
        {
          "id": "m23",
          "quote": "A broken line at the left of your lane means you may pass if the way is clear. ('A' may pass if there are enough broken lines ahead to complete the pass safely.)"
        },
        {
          "id": "m24",
          "quote": "vehicles travelling beside broken yellow lines"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "clear",
          "note": "The driver must judge whether the way is clear of oncoming traffic."
        },
        {
          "code": "J",
          "span": "enough",
          "note": "No number of broken lines is given; the driver must judge how many are enough."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No measure of safety is given; the driver must judge whether the pass can be completed safely."
        }
      ],
      "links": [],
      "note": null
    }
  ]
}
